using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OperationsRequests.Data;using OperationsRequests.Domain;using OperationsRequests.Services;namespace OperationsRequests.Pages;[Authorize]public class IndexModel(ApplicationDbContext db,UserManager<ApplicationUser> users,ScopeService scope):PageModel{public List<TrainingRequest> Requests{get;set;}=[];public Dictionary<RequestStatus,int> ByStatus{get;set;}=[];public Dictionary<RequestPriority,int> ByPriority{get;set;}=[];public Dictionary<RequestType,int> ByType{get;set;}=[];public Dictionary<string,int> ByOrganisation{get;set;}=[];public int Total=>Requests.Count;public int Open=>Requests.Count(x=>x.Status is not RequestStatus.Approved and not RequestStatus.Declined and not RequestStatus.Resolved);public int Overdue=>Requests.Count(x=>x.CreatedAt<DateTimeOffset.UtcNow.AddDays(-7)&&x.Status is not RequestStatus.Resolved and not RequestStatus.Declined);public async Task OnGetAsync(){var u=await users.GetUserAsync(User)??throw new UnauthorizedAccessException();var roles=await users.GetRolesAsync(u);var all=await db.TrainingRequests.Include(x=>x.Site).ThenInclude(x=>x.Territory).ThenInclude(x=>x.Country).Include(x=>x.RequestedBy).OrderByDescending(x=>x.CreatedAt).ToListAsync();Requests=all.Where(x=>scope.CanView(x,u,roles)).ToList();ByStatus=Requests.GroupBy(x=>x.Status).ToDictionary(x=>x.Key,x=>x.Count());ByPriority=Requests.GroupBy(x=>x.Priority).ToDictionary(x=>x.Key,x=>x.Count());ByType=Requests.GroupBy(x=>x.Type).ToDictionary(x=>x.Key,x=>x.Count());ByOrganisation=Requests.GroupBy(x=>$"{x.Site.Territory.Country.Name} / {x.Site.Territory.Name} / {x.Site.Name}").ToDictionary(x=>x.Key,x=>x.Count());}}
